using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
using kok;
class ModuleTests {
 static bool Reject(Action a){try{a();return false;}catch(InvalidDataException){return true;}catch(InvalidOperationException){return true;}}
 static ModuleContext Context(Library lib,Func<bool> current=null){return new ModuleContext(lib,null,new ModulePolicy(lib,current),null,CancellationToken.None,null,new Operations(lib,null),new Jobs(lib.DataDir,null));}
 public static void Run(string root,Action<bool,string> check){
  var lib=new Library(root);var ctx=Context(lib);var registry=ModuleRegistry.Builtins;
  check(registry.Modules.Single(m=>m.Name=="legacy").Required&&registry.Modules.SelectMany(m=>m.Actions??new ActionSpec[0]).All(a=>a.Requires.HasValue&&a.Writes.HasValue&&a.Schema!=null),"every native action, including explicit legacy actions, declares schema and policy");
  var create=registry.Capabilities.Single(c=>c.id=="documents.createDocument");check(create.tool.Name=="create_document"&&create.actions.Any(a=>a.Name=="createDocument")&&create.actions.Any(a=>a.Name=="commandDocument")&&create.surfaces.Contains("palette")&&create.module=="documents","one capability owns the UI action, palette command and Agent tool adapters");
  var local=new ModuleRegistry();int executed=0;var protectedAction=new ActionSpec{Name="network",Requires=Need.Network|Need.NormalLibrary,Writes=false,Kind="read",Schema=CapabilitySchema.Obj(),Execute=(c,a)=>{executed++;return Task.FromResult((object)true);}};
  local.Register(new KokModule{Name="fixture-policy",Actions=new[]{protectedAction}});
  check(Reject(()=>local.Dispatch(ctx,"network",new Dictionary<string,object>()).GetAwaiter().GetResult())&&executed==0,"Pure mode rejects network actions before their handlers run");
  lib.SetAppMode("smart",true);local.Dispatch(ctx,"network",new Dictionary<string,object>()).GetAwaiter().GetResult();check(executed==1,"declared policy allows Smart-mode actions without changing their handlers");
  check(Reject(()=>local.Dispatch(Context(lib,()=>false),"network",new Dictionary<string,object>()).GetAwaiter().GetResult())&&executed==1,"a stale library context cannot execute an action after scope changes");
  check(Reject(()=>local.Register(new KokModule{Name="missing-policy",Actions=new[]{new ActionSpec{Name="missing",Schema=CapabilitySchema.Obj(),Writes=false,Kind="read",Execute=(c,a)=>Task.FromResult((object)true)}}})),"registration rejects an action with no explicit permission declaration");
  check(Reject(()=>CapabilitySchema.Check(registry.Capabilities.SelectMany(c=>c.actions).Single(c=>c.Name=="jobAction").Schema,new Dictionary<string,object>{{"id","a"},{"action","shell"}}))&&Reject(()=>CapabilitySchema.Check(registry.Capabilities.SelectMany(c=>c.actions).Single(c=>c.Name=="createDocument").Schema,new Dictionary<string,object>{{"name","a"},{"format","md"},{"path","outside"}})),"schema validation rejects invalid enums and unexpected path parameters");
  lib.SetModuleEnabled("presentations",false);check(!Library.Json.Serialize(AgentRules.Schemas(true,lib)).Contains("create_presentation"),"disabling a module removes its tool from provider schemas");
  check(Reject(()=>registry.Dispatch(ctx,"newPresentation",new Dictionary<string,object>{{"name","blocked"},{"base64","invalid"}}).GetAwaiter().GetResult()),"disabled modules reject native calls before decoding content");
  var state=new AgentTaskState{id=Guid.NewGuid().ToString("N"),options=new AgentTaskOptions()};check(Reject(()=>lib.WriteAgentTool(state,new AgentCall{tool="create_presentation"},CancellationToken.None)),"a disabled module also rejects a direct Agent tool execution");lib.SetModuleEnabled("presentations",true);
  check(Reject(()=>lib.SetModuleEnabled("core",false)),"required shell modules cannot be disabled");
  check(Reject(()=>registry.Dispatch(ctx,"setModuleEnabled",new Dictionary<string,object>{{"id","unknown-module"},{"enabled",false}}).GetAwaiter().GetResult()),"unknown module IDs are rejected by schema before stop or settings side effects");
  var a=lib.CreateDocument("First","md","","source");var b=lib.CreateDocument("Second","md","","source");
  check(Reject(()=>lib.Update(a.id,new Dictionary<string,object>{{"favorite",true},{"unknownFacetField",true}}))&&!lib.Find(a.id).favorite,"undeclared fields are rejected before any part of a patch changes the item");
  var ops=new Operations(lib,null);var changes=new List<AgentChange>{new AgentChange{id=a.id,before=new Dictionary<string,object>{{"notes",""}},after=new Dictionary<string,object>{{"notes","A"}}},new AgentChange{id=b.id,before=new Dictionary<string,object>{{"notes",""}},after=new Dictionary<string,object>{{"notes","B"}}}};
  var op=ops.Propose("Fixture edit","operations","user",changes);check(lib.Find(a.id).notes==""&&op.state=="proposed","a batch operation proposal does not modify items");lib.Update(b.id,new Dictionary<string,object>{{"notes","manual"}});
  check(Reject(()=>ops.Apply(op.id))&&lib.Find(a.id).notes==""&&lib.Find(b.id).notes=="manual","one conflict prevents the entire operation from partially applying");lib.Update(b.id,new Dictionary<string,object>{{"notes",""}});ops.Apply(op.id);ops.Apply(op.id);check(lib.Find(a.id).notes=="A"&&ops.List().Count(o=>o.id==op.id)==1,"apply is idempotent and keeps one audit record");
  lib.Update(a.id,new Dictionary<string,object>{{"notes","later"}});check(Reject(()=>ops.Undo(op.id))&&lib.Find(a.id).notes=="later","global undo preserves later manual changes");lib.Update(a.id,new Dictionary<string,object>{{"notes","A"}});ops.Undo(op.id);check(lib.Find(a.id).notes==""&&ops.List().Single(o=>o.id==op.id).state=="undone"&&ops.List().Single(o=>o.id==op.id).patches.Count==2,"undo retains the complete operation record and before/after values");
  var skipped=lib.ProposeBulkCollection(new List<string>{a.id},"not applied");ops.Skip(skipped.id);check(lib.Find(a.id).collection==""&&lib.OperationStatus(skipped.id)=="skipped"&&Reject(()=>ops.Apply(skipped.id)),"skip is durable and cannot accidentally apply through the same operation ID");
  string creation=Guid.NewGuid().ToString("N");var created=lib.CreateDocument("Tracked","md","","kept bytes",creation,"user");check(new Library(root).OperationStatus(creation)=="applied","new document and creation history commit together");ops.Undo(creation);check(lib.Find(created.id)==null&&File.Exists(created.path),"undoing creation removes only the index entry and preserves the disk file");
  int items=lib.Db.items.Count,history=ops.List().Count;bool failed=false;using(var locked=new FileStream(lib.StoragePath,FileMode.Open,FileAccess.Read,FileShare.None)){try{lib.CreateDocument("Failed commit","md","","x",Guid.NewGuid().ToString("N"),"user");}catch(IOException){failed=true;}}check(failed&&lib.Db.items.Count==items&&ops.List().Count==history,"a failed creation commit rolls back both the item and its operation");
  string privateRoot=Path.Combine(root,"private");using(var vault=VaultSession.Create(privateRoot,"OnlyForLocalFixture928!")){var secret=new Library(privateRoot,vault);var e=new Entry{id=Guid.NewGuid().ToString("N"),name="private",kind="document",path="",ext="MD",notes=""};secret.Db.items.Add(e);secret.Save();var privateOps=new Operations(secret,null);var p=privateOps.Propose("private","operations","user",new List<AgentChange>{new AgentChange{id=e.id,before=new Dictionary<string,object>{{"notes",""}},after=new Dictionary<string,object>{{"notes","PRIVATE_OPERATION_SENTINEL"}}}});privateOps.Apply(p.id);check(!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(privateRoot,"library.vault"))).Contains("PRIVATE_OPERATION_SENTINEL"),"private operation history stays inside the password-encrypted library");check(Reject(()=>new ModulePolicy(secret).Ensure(Need.NormalLibrary,"agent")),"normal-library actions cannot cross into the private library");}
 }
}
